// Placeholder Firebase options for CI. The real `lib/firebase_options.dart`
// is generated by `flutterfire configure` and kept out of git (the repo is
// public); CI copies this file in its place so the app compiles. The tests
// never call Firebase. See docs/FIREBASE.md.
import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart'
    show TargetPlatform, defaultTargetPlatform;

class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform => switch (defaultTargetPlatform) {
    TargetPlatform.android => android,
    TargetPlatform.iOS => ios,
    _ => throw UnsupportedError('Firebase is set up for Android and iOS only.'),
  };

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'ci-placeholder',
    appId: '1:000000000000:android:0000000000000000000000',
    messagingSenderId: '000000000000',
    projectId: 'ci-placeholder',
  );

  static const FirebaseOptions ios = FirebaseOptions(
    apiKey: 'ci-placeholder',
    appId: '1:000000000000:ios:0000000000000000000000',
    messagingSenderId: '000000000000',
    projectId: 'ci-placeholder',
    iosBundleId: 'com.luminalabs.monumentalhabits',
  );
}
